from pathlib import Path
from html import escape
from entity_pages import write_entity, presentation_credit

ROOT = Path(__file__).resolve().parents[1]

def icon(name='arrow-up-right'):
    return f'<img class="icon" src="assets/{name}.svg" alt="" width="20" height="20" aria-hidden="true">'

def button(label, href='plan.html', secondary=False, name='arrow-up-right'):
    return f'<a class="button{" secondary" if secondary else ""}" href="{href}">{label}{icon(name)}</a>'

def link(label, href, name='arrow-up-right'):
    return f'<a class="text-link" href="{href}">{label}{icon(name)}</a>'

def photo(file, alt, cls='portfolio-photo', eager=False):
    return f'<div class="photo {cls}"><img src="assets/{file}.webp" alt="{escape(alt)}" width="808" height="632" {"fetchpriority=high" if eager else "loading=lazy"}></div>'

