    ('residence','Two-storey residence','Residential','residence','171738453/TWO-(2)-STOREY-RESIDENCE'),
    ('bungalow','Bungalow house','Residential','bungalow','171732827/BUNGALOW-HOUSE'),
    ('basement','Residence with basement','Residential','basement','171733601/ONE-STOREY-RESIDENTIAL-WITH-BASEMENT'),
    ('roofdeck','Residence with roof deck','Residential','roofdeck','171734435/TWO-STOREY-RESIDENTIAL-W-ROOFDECK'),
