    nav=''.join(f'<a href="{file}.html" {"aria-current=page" if page==key else ""}>{label}</a>' for key,file,label in [('projects','projects','Projects'),('services','services','Services'),('process','process','Process'),('about','about','About us'),('resources','resources','Resources')])
