def page_head(title,desc,label=None):
    return f'<div class="container"><div class="page-head">{f"<span class=eyebrow>{label}</span>" if label else ""}<h1>{title}</h1><p>{desc}</p></div></div>'

def write(filename,title,desc,page,content):
    branded_footer = footer().replace('</div></div></footer>', '</div>'+presentation_credit()+'</div></footer>')
    (ROOT/filename).write_text((head(title,desc,page)+content+branded_footer).replace('</body>',(ROOT/'tools/assistant-fragment.html').read_text(encoding='utf-8')+'</body>'),encoding='utf-8')

