write('resources.html','Planning resources','Practical questions and planning guides for your first project conversation.','resources',page_head('Better questions.<br>Better starting points.','Practical reading for the decisions you will make before, during, and after a build.')+f'<section class="container" style="padding-bottom:70px"><div class="notice">These are general project-planning guides. Project-specific requirements and technical decisions belong with the relevant qualified professionals.</div><div class="resource-grid">{resources}</div></section>'+closing())

write('guide.html','First meeting guide','Prepare a useful project brief and make the first conversation count.','guide',f'<div class="container"><div class="page-head"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="resources.html">Resources</a>{icon("arrow-right")}<span id="article-category">First meeting</span></nav><h1 id="article-title">What to bring to your first project meeting.</h1><p id="article-lead">You do not need every answer. Bring the information you have and the questions you need to resolve.</p></div><section class="article-layout"><aside class="article-aside"><div class="contact-card"><h3>Make it your own.</h3><p>Capture your priorities in a project brief you can download and bring to the conversation.</p>{button("Plan my build")}</div></aside><article class="article-content" id="article-content"><h2>Start with how the place will be used.</h2><p>Describe who the space is for, what it needs to support, and what matters most to you. A few clear priorities are more useful than an unfiltered list of every possible feature.</p><h2>Bring the information you already have.</h2><p>Location, approximate area, available drawings, photographs, and site information help the team understand where the discussion should begin.</p><h2>Talk about decisions and assumptions.</h2><p>Explain your budget preference and timing. Ask what is known, what still needs verification, and what must be decided before a scope or estimate can be reviewed.</p><h2>Your first-meeting checklist.</h2><div class="checklist">'+''.join(f'<label class="check-item"><input type="checkbox"><span>{x}</span></label>' for x in ['Site location and information you can share','Intended use and approximate floor area','A small set of reference images','Your main priorities and must-haves','Budget preference and timing','Available drawings and outstanding questions'])+f'</div><p class="small" style="margin-top:28px">General planning guidance only. Confirm project-specific technical and approval requirements with the relevant professionals.</p></article></section></div>{closing("Turn your questions into a starting brief.")}')

TYPE_OPTIONS=''.join(f'<option>{x}</option>' for x in ['Residence','Renovation','Commercial space','Apartment building'])
PRIORITIES=['Natural light','Room to grow','Easy maintenance','Work-from-home space','Outdoor connection','Accessible everyday use']
write('plan.html','Plan my build','Create a local project brief with your scope, priorities, and open questions.','plan',page_head('From an idea.<br>To a clearer brief.','Three short steps. A project dossier you can download, edit, and bring to the first conversation.')+f'''<p class="container print-referral">Only need printed copies? <a class="text-link" href="blueprinting.html">Visit the independent Blueprinting business<img class="icon" src="assets/arrow-up-right.svg" alt="" width="20" height="20"></a></p><section class="container wizard-layout"><div class="wizard"><nav class="wizard-nav" aria-label="Brief progress"><span data-progress="0" aria-current="step">The place</span><span data-progress="1">The direction</span><span data-progress="2">The priorities</span></nav><form id="brief-form" novalidate><div class="wizard-body"><section data-step="0"><h2>Tell us about the place.</h2><p>Use an approximate area if you are still working through the plan.</p><div class="form-grid"><div class="field"><label for="brief-type">Project type</label><select id="brief-type" name="type">{TYPE_OPTIONS}</select></div><div class="field"><label for="brief-city">City or municipality</label><input id="brief-city" name="city" placeholder="e.g. Antipolo" minlength="2" maxlength="80" required autocomplete="address-level2"></div><div class="field"><label for="brief-area">Approx. total floor area, m²</label><input id="brief-area" name="area" type="number" min="20" max="2000" step="1" value="120" required><span class="field-help">Total enclosed floor area across all levels.</span></div><div class="field full"><label for="brief-service">What help do you need?</label><select id="brief-service" name="service"><option>Design &amp; build</option><option value="Blueprint / plan set only">Plan preparation / engineering</option><option>Construction only</option><option>Renovation &amp; fit-out</option><option>Help me decide</option></select></div><div class="field"><label for="brief-site">Site information</label><select id="brief-site" name="site"><option value="To confirm">Still exploring a site</option><option value="Available">Site information available</option><option value="Existing property">Existing property to assess</option></select></div></div></section><section data-step="1" hidden><h2>Set a direction.</h2><p>These are preferences for a discussion, not a quotation or a confirmed schedule.</p><div class="form-grid"><div class="field"><label for="brief-finish">Finish preference</label><select id="brief-finish" name="finish"><option>Help me decide</option><option>Standard</option><option>Mid-range</option><option>Premium</option></select></div><div class="field"><label for="brief-budget">Budget preference</label><select id="brief-budget" name="budget"><option>Discuss with the team</option><option>Below PHP 3 million</option><option>PHP 3-5 million</option><option>PHP 5-8 million</option><option>Above PHP 8 million</option></select></div><div class="field"><label for="brief-timing">When are you hoping to begin?</label><select id="brief-timing" name="timing"><option>Still exploring</option><option>Within 3 months</option><option>Within 6 months</option><option>Later than 6 months</option></select></div><div class="field"><label for="brief-drawings">Available drawings</label><select id="brief-drawings" name="drawings"><option>Not yet</option><option>Concept drawings</option><option>Drawings for review</option></select></div></div></section><section data-step="2" hidden><h2>Make room for what matters.</h2><p>Choose the priorities you want the team to understand.</p><fieldset><legend>Your priorities</legend><div class="option-grid">'''+''.join(f'<label class="option"><input type="checkbox" name="priority" value="{x}"><span>{x}</span></label>' for x in PRIORITIES)+f'''</div></fieldset><div class="field" style="margin-top:28px"><label for="brief-notes">Anything else we should understand?</label><textarea id="brief-notes" name="notes" maxlength="1000" placeholder="What would make the project feel right for you?"></textarea><span class="field-help">Avoid sensitive personal information. This brief stays in your browser tab.</span></div></section><p class="form-status form-error" id="brief-error" role="alert" hidden></p></div><div class="wizard-footer"><button class="button secondary small" type="button" id="brief-back" hidden>{icon("arrow-left")}Back</button><button class="button" type="submit" id="brief-next">Continue{icon("arrow-right")}</button></div></form><section class="wizard-body" id="brief-result" hidden aria-labelledby="brief-result-title"><div class="brief-cover"><small>Your starting brief</small><h2 id="brief-result-title">The project you have in mind.</h2><dl id="brief-facts"></dl></div><h3>Your priorities</h3><p class="brief-priorities" id="brief-priorities"></p><div class="precheck"><h3>Planning assistant: open questions</h3><p class="small">Rule-based demo. These prompts come from your answers; no AI service or drawing analysis is connected.</p><ul id="brief-checks"></ul></div><div class="row"><button class="button" type="button" id="brief-download">Download my brief{icon("download")}</button><button class="button secondary" type="button" id="brief-edit">Edit brief{icon("arrow-left")}</button></div><p class="small" style="margin-top:24px">This is a planning record, not a quotation. Discuss drawings, site conditions, quantities, and professional review with the team.</p><div style="margin-top:28px">{link("Contact the company on Facebook","https://www.facebook.com/calluengconstruction")}</div><details style="margin-top:30px"><summary style="font-size:1rem">Explore a sample budget allowance{icon("plus")}</summary><div class="detail-body"><p class="small">Fixed demonstration rates only. These are not current market rates or a company estimate.</p><div id="budget-example" class="form-status"></div><p class="small" style="margin-top:18px">Excludes VAT, permits, professional fees, land, contingencies, and special site work. Real pricing requires measured quantities and reviewed specifications.</p></div></details><p class="form-status" id="brief-download-status" role="status" hidden></p></section></div><aside class="wizard-aside"><div class="contact-card"><h3>Your Build Brief</h3><p>A place to bring your ideas into focus.</p><div class="stack small" style="margin-top:25px"><span>Project scope and location</span><span>Preferences and priorities</span><span>Questions to resolve together</span><span>A downloadable conversation record</span></div><p class="small" style="margin-top:25px" id="brief-save-status">Drafts stay in this browser tab’s session. Nothing is sent.</p></div><p class="small" style="margin-top:24px">Not sure about something? Choose the option closest to what you know. The team can help resolve it.</p></aside></section>''')

write('client-care.html','Client care','Explore the proposed client-care experience for project updates, documents, and decisions.','client-care',page_head('Stay close.<br>To every decision.','A proposed client workspace that keeps the project conversation, approved records, and next decisions together.')+f'''<section class="container portal-banner"><div><h2>Less chasing.<br>More understanding.</h2><p>See what was approved, what happens next, and what the team needs from you.</p>{button("Explore the sample workspace","#workspace",True,"arrow-right")}</div>{photo("bungalow","Published bungalow portfolio used to illustrate the proposed client-care experience","")}</section><section class="section container"><div class="portal-preview" id="workspace"><div class="portal-top"><div><span class="tag">Interactive sample workspace</span><h2>Santos residence</h2><p class="small" style="margin-top:12px">Fictional client and project records. Nothing is sent or committed.</p></div><span class="tag" id="portal-status">1 decision to review</span></div><div class="portal-tabs" role="tablist" aria-label="Sample project workspace"><button type="button" role="tab" id="tab-overview" aria-selected="true" aria-controls="panel-overview" data-tab="overview">Overview</button><button type="button" role="tab" id="tab-decisions" aria-selected="false" aria-controls="panel-decisions" data-tab="decisions" tabindex="-1">Decisions</button><button type="button" role="tab" id="tab-documents" aria-selected="false" aria-controls="panel-documents" data-tab="documents" tabindex="-1">Documents</button><button type="button" role="tab" id="tab-messages" aria-selected="false" aria-controls="panel-messages" data-tab="messages" tabindex="-1">Messages</button></div><section id="panel-overview" role="tabpanel" aria-labelledby="tab-overview"><div class="portal-grid"><div><h3>Where the sample project stands</h3><div class="milestones"><article><strong>Planning</strong><small>Complete example</small></article><article><strong>Foundation</strong><small>Complete example</small></article><article class="current"><strong>Structural works</strong><small>In progress example</small></article><article><strong>Roofing & finishes</strong><small>Upcoming example</small></article></div><div class="portal-panel"><h3>Latest update</h3><p>The sample team is resolving inspection items before the next structural milestone. An exterior finish selection is ready for review.</p><button class="button secondary small" type="button" data-portal-next="decisions" style="margin-top:22px">Review the decision{icon("arrow-right")}</button></div></div><aside class="portal-panel"><h3>Next on the agenda</h3><p>Confirm the exterior accent finish. The sample selection sits within the illustrative allowance.</p><p style="margin-top:22px">Any real change would need the specification, cost, and schedule impact reviewed before approval.</p></aside></div></section><section id="panel-decisions" role="tabpanel" aria-labelledby="tab-decisions" hidden><div class="selection"><div class="swatch" aria-label="Illustrative warm stone paint colour"></div><div><h3>Exterior accent finish</h3><p>Warm stone textured paint for the entrance accent wall. Within the sample allowance.</p><div class="row" id="portal-decision-actions"><button class="button small" type="button" id="approve-finish">Approve in demo{icon("check")}</button><button class="button secondary small" type="button" data-portal-next="messages">Ask for another option{icon("arrow-right")}</button></div><div class="form-status" id="portal-approval-status" role="status" hidden></div></div></div><p class="small">Demo approval creates no real scope change, order, contract, or financial commitment.</p></section><section id="panel-documents" role="tabpanel" aria-labelledby="tab-documents" hidden><div class="document-row"><div><strong>Weekly progress update</strong><p>Approved sample record</p></div><button class="button secondary small" type="button" data-document="update">Preview{icon()}</button></div><div class="document-row"><div><strong>Drawing register</strong><p>Sample revision record</p></div><button class="button secondary small" type="button" data-document="drawings">Preview{icon()}</button></div><div class="document-row"><div><strong>Handover checklist</strong><p>Sample completion record</p></div><button class="button secondary small" type="button" data-document="handover">Preview{icon()}</button></div></section><section id="panel-messages" role="tabpanel" aria-labelledby="tab-messages" hidden><div class="conversation" id="conversation"><article class="message"><strong>Mika Dela Cruz, sample project manager</strong><p>The exterior finish proposal is ready for your review. Let us know if you would like another option.</p></article></div><form class="message-form" id="portal-message-form"><div class="field"><label for="portal-message">Your message</label><textarea id="portal-message" maxlength="1500" required placeholder="Ask about the sample project…"></textarea></div><button class="button" type="submit">Add demo message{icon("arrow-right")}</button><p class="form-status" id="portal-message-status" role="status" hidden></p></form></section></div></section><section class="container"><div class="faq-grid"><h2>A clear record.<br>With the right access.</h2><div>{faqs([FAQ[3],FAQ[4]])}<details><summary>What would a live workspace need?{icon("plus")}</summary><div class="detail-body"><p>Secure sign-in, project-specific permissions, versioned documents, approved updates, and an auditable decision record. This page demonstrates the proposed experience only.</p></div></details></div></div></section>{closing()}''')

